import { useState } from "react";

const theme = {
  primary: "#9400D3",
  accent: "#ED80E9",
  lightPurple: "#D3D3FF",
  muted: "#D8BFD8",
  white: "#ffffff",
  dark: "#1a1a2e",
};

const HomeIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 9.5L12 3l9 6.5V20a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V9.5z" />
    <path d="M9 21V12h6v9" />
  </svg>
);

const SearchIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="11" cy="11" r="8" fill={filled ? "currentColor" : "none"} opacity={filled ? 0.15 : 1} />
    <circle cx="11" cy="11" r="8" />
    <line x1="21" y1="21" x2="16.65" y2="16.65" />
  </svg>
);

const CategoryIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <rect x="3" y="3" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} opacity={filled ? 0.9 : 1} />
    <rect x="14" y="3" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} opacity={filled ? 0.9 : 1} />
    <rect x="3" y="14" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} opacity={filled ? 0.9 : 1} />
    <rect x="14" y="14" width="7" height="7" rx="1" fill={filled ? "currentColor" : "none"} opacity={filled ? 0.9 : 1} />
  </svg>
);

const WishlistIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
  </svg>
);

const ProfileIcon = ({ filled }) => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
    <circle cx="12" cy="7" r="4" fill={filled ? "currentColor" : "none"} opacity={filled ? 0.9 : 1} />
  </svg>
);

const navTabs = [
  { id: "home",     label: "Home",     Icon: HomeIcon },
  { id: "search",   label: "Search",   Icon: SearchIcon },
  { id: "category", label: "Category", Icon: CategoryIcon },
  { id: "wishlist", label: "Wishlist", Icon: WishlistIcon },
  { id: "profile",  label: "Profile",  Icon: ProfileIcon },
];

export default function BottomNav() {
  const [active, setActive] = useState("home");

  return (
    <>
      {/* spacer so page content isn't hidden behind bar */}
      <div style={{ height: 70 }} />

      <nav style={{
        position: "fixed",
        bottom: 0,
        left: 0,
        right: 0,
        height: 64,
        background: theme.white,
        borderTop: `1.5px solid ${theme.lightPurple}`,
        boxShadow: `0 -4px 20px rgba(148,0,211,0.12)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "space-around",
        zIndex: 9999,
        fontFamily: "'Helvetica Neue', Arial, sans-serif",
        padding: "0 8px",
      }}>
        {navTabs.map(({ id, label, Icon }) => {
          const isActive = active === id;
          return (
            <button
              key={id}
              onClick={() => setActive(id)}
              style={{
                background: "none",
                border: "none",
                cursor: "pointer",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: 3,
                flex: 1,
                padding: "6px 0",
                position: "relative",
                color: isActive ? theme.primary : "#aaa",
                transition: "color 0.2s",
              }}
            >
              {/* active pill indicator */}
              {isActive && (
                <span style={{
                  position: "absolute",
                  top: -1,
                  left: "50%",
                  transform: "translateX(-50%)",
                  width: 32,
                  height: 3,
                  borderRadius: "0 0 4px 4px",
                  background: `linear-gradient(90deg, ${theme.primary}, ${theme.accent})`,
                }} />
              )}

              {/* icon with active bg bubble */}
              <span style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                width: 36,
                height: 36,
                borderRadius: "50%",
                background: isActive ? `${theme.lightPurple}66` : "transparent",
                transition: "background 0.2s",
              }}>
                <Icon filled={isActive} />
              </span>

              <span style={{
                fontSize: 10,
                fontWeight: isActive ? 700 : 500,
                letterSpacing: 0.3,
                color: isActive ? theme.primary : "#aaa",
                transition: "color 0.2s",
              }}>
                {label}
              </span>
            </button>
          );
        })}
      </nav>
    </>
  );
}
